import{_ as a,o as e,c as l,a2 as o}from"./chunks/framework.Crpw6aS5.js";const c=JSON.parse('{"title":"透视盈利 Look-Through Earnings","description":"巴菲特最重要的财务概念之一：为什么留存收益比股息更有价值","frontmatter":{"title":"透视盈利 Look-Through Earnings","description":"巴菲特最重要的财务概念之一：为什么留存收益比股息更有价值"},"headers":[],"relativePath":"02_concepts/look-through-earnings.md","filePath":"02_concepts/look-through-earnings.md"}'),r={name:"02_concepts/look-through-earnings.md"};function i(n,t,s,h,p,u){return e(),l("div",null,[...t[0]||(t[0]=[o(`<h1 id="透视盈利-look-through-earnings" tabindex="-1">透视盈利 Look-Through Earnings <a class="header-anchor" href="#透视盈利-look-through-earnings" aria-label="Permalink to &quot;透视盈利 Look-Through Earnings&quot;">​</a></h1><blockquote><p>1980年，巴菲特在致股东信中首次提出&quot;透视盈利&quot;概念。他用&quot;森林生长的树&quot;的比喻，解释了为什么持股低于20%的优秀公司，其留存盈利与已报告股息收益具有完全等价的经济价值。这是理解伯克希尔真实盈利能力的关键。</p></blockquote><hr><h2 id="核心出处" tabindex="-1">核心出处 <a class="header-anchor" href="#核心出处" aria-label="Permalink to &quot;核心出处&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">年份</th><th style="text-align:left;">重点内容</th></tr></thead><tbody><tr><td style="text-align:left;"><strong><a href="/01_letters/1980年/翻译.html">1980年翻译</a></strong></td><td style="text-align:left;">首次系统阐述，森林生长的树比喻</td></tr><tr><td style="text-align:left;"><strong><a href="/01_letters/1990年/翻译.html">1990年翻译</a></strong></td><td style="text-align:left;">透视盈利表正式纳入年报，成为伯克希尔最重要的财务追踪体系</td></tr><tr><td style="text-align:left;"><strong><a href="/01_letters/2004年/翻译.html">2004年翻译</a></strong></td><td style="text-align:left;">透视盈利与内在价值的关系深化</td></tr></tbody></table><hr><h2 id="一、-森林生长的树-的比喻" tabindex="-1">一、&quot;森林生长的树&quot;的比喻 <a class="header-anchor" href="#一、-森林生长的树-的比喻" aria-label="Permalink to &quot;一、&quot;森林生长的树&quot;的比喻&quot;">​</a></h2><p>1980年，巴菲特在信中解释了为什么GEICO的未分配盈利如此重要：</p><blockquote><p>&quot;如果一片森林长在我们部分拥有的树林里，哪怕财务报表没记录生长，我们依然拥有一部分树。当我们的树木生长时，无论是已记录在报表还是未记录，我们都一样富有。&quot;</p></blockquote><p>GEICO当年报告股息收益300万美元，但巴菲特估计伯克希尔占有的实际盈利约为2,000万美元——<strong>后者是前者的6.7倍</strong>，而且这2,000万几乎不需要额外资本投入。</p><p>这一洞察彻底改变了巴菲特衡量伯克希尔真实盈利的方式。</p><hr><h2 id="二、为什么留存收益比股息更有价值" tabindex="-1">二、为什么留存收益比股息更有价值 <a class="header-anchor" href="#二、为什么留存收益比股息更有价值" aria-label="Permalink to &quot;二、为什么留存收益比股息更有价值&quot;">​</a></h2><p>巴菲特的核心论点：<strong>留存收益比股息再投资更合算，因为省去了双重税收。</strong></p><p>当一家公司向股东支付股息时：</p><ol><li>公司先缴纳企业所得税（25%或更高）</li><li>股东收到股息后再缴纳个人所得税</li><li>实际到股东手里的，可能只有原始利润的60%左右</li></ol><p>当一家公司留存收益时：</p><ol><li>留存收益在企业内部以25%的税率（伯克希尔的穿透税率）再投资</li><li>只要股东不卖出，就不需要缴纳资本利得税</li><li>递延纳税意味着复利可以在税前基数上继续运作</li></ol><p>巴菲特在1990年信中明确：</p><blockquote><p>&quot;留存收益比股息再投资更合算，因为省去了双重税收。&quot;</p></blockquote><hr><h2 id="三、透视盈利表-伯克希尔的财务追踪体系" tabindex="-1">三、透视盈利表：伯克希尔的财务追踪体系 <a class="header-anchor" href="#三、透视盈利表-伯克希尔的财务追踪体系" aria-label="Permalink to &quot;三、透视盈利表：伯克希尔的财务追踪体系&quot;">​</a></h2><p>从1990年开始，伯克希尔将透视盈利正式纳入年报，成为最重要的财务追踪体系。</p><p>透视盈利的计算方式：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>透视盈利 = </span></span>
<span class="line"><span>  伯克希尔报告的营业利润</span></span>
<span class="line"><span>  + 被投资公司留存盈利中伯克希尔占有的部分（按持股比例）</span></span>
<span class="line"><span>  - 假设这些留存盈利按正常税率应缴纳的税款</span></span></code></pre></div><p>巴菲特的目标：</p><blockquote><p>&quot;透视盈利每年增长15%。&quot;</p></blockquote><p>这是他评估伯克希尔真实经济表现的核心指标，比GAAP净利润更准确。</p><hr><h2 id="四、透视盈利与内在价值的关系" tabindex="-1">四、透视盈利与内在价值的关系 <a class="header-anchor" href="#四、透视盈利与内在价值的关系" aria-label="Permalink to &quot;四、透视盈利与内在价值的关系&quot;">​</a></h2><p>透视盈利是估算内在价值的重要输入。</p><p>巴菲特在2004年信中阐述了内在价值的驱动因素：</p><blockquote><p>&quot;内在价值的两大驱动因素：每股投资额 + 每股税前盈利&quot;</p></blockquote><p>透视盈利正是衡量&quot;每股盈利&quot;最准确的方式——它包含了被投资公司留存收益中属于伯克希尔的份额。</p><p>两者关系：</p><ul><li>透视盈利持续增长 → 内在价值持续增长</li><li>透视盈利的增长率是伯克希尔&quot;经济商誉&quot;积累速度的最好指标</li><li>当透视盈利增长率高于账面价值增长率时，说明商誉在增加</li></ul><hr><h2 id="五、对投资决策的启示" tabindex="-1">五、对投资决策的启示 <a class="header-anchor" href="#五、对投资决策的启示" aria-label="Permalink to &quot;五、对投资决策的启示&quot;">​</a></h2><p><strong>为什么伯克希尔很少支付股息</strong>：</p><ul><li>股息需要缴纳双重税收</li><li>留存收益可以在递延纳税的状态下复利增长</li><li>股东可以通过卖出少量股票来&quot;变现&quot;，享受递延税的优势</li></ul><p><strong>为什么投资者应该关注透视盈利</strong>：</p><ul><li>持股比例低于20%的公司，留存收益不会反映在你的报表里</li><li>但这些未记录的&quot;树木&quot;确实在生长，你拥有一部分</li><li>这是伯克希尔内在价值远超账面价值的根本原因</li></ul><hr><h2 id="相关主题" tabindex="-1">相关主题 <a class="header-anchor" href="#相关主题" aria-label="Permalink to &quot;相关主题&quot;">​</a></h2><ul><li><a href="./deferred-tax.html">递延税复利 Deferred Tax Compounding</a> — 递延纳税与复利的结合</li><li><a href="./intrinsic-value.html">内在价值 Intrinsic Value</a> — 透视盈利是内在价值的重要驱动</li><li><a href="./compounding.html">复利 Compounding</a> — 时间是伟大事业的朋友</li></ul><h2 id="关键原文出处" tabindex="-1">关键原文出处 <a class="header-anchor" href="#关键原文出处" aria-label="Permalink to &quot;关键原文出处&quot;">​</a></h2><p>以下为该主题在致股东信中的关键原文出处年份，点击即可阅读完整翻译：</p><ul><li><a href="/search.html?q=1980年：首次提出">完整翻译|/01_letters/1980年/翻译</a></li><li><a href="/search.html?q=1990年：体系化">完整翻译|/01_letters/1990年/翻译</a></li><li><a href="/search.html?q=2004年：深化">完整翻译|/01_letters/2004年/翻译</a></li></ul>`,48)])])}const q=a(r,[["render",i]]);export{c as __pageData,q as default};
